function update_enemy(e)
 e.x+=e.dx e.y+=e.dy
 if e.x<0 then e.x=0 e.dx=-e.dx end
 if e.x>127 then e.x=127 e.dx=-e.dx end
 if e.y<0 then e.y=0 e.dy=-e.dy end
 if e.y>127 then e.y=127 e.dy=-e.dy end
end
